import{validateProjection,type StorySaveProjection}from'./story-domain.ts'
import type{StoryPack}from'./game-library.ts'
/** One save's summary from the host list endpoint. */
export interface SaveSummary{saveId:string;packId:string;packTitle:string;revision:number;updatedAt:string;sceneLabel:string}
export class HostProjectionStorage{private tail:Promise<void>=Promise.resolve();constructor(private readonly fetcher:typeof fetch=(input,init)=>fetch(input,init)){}async listPacks():Promise<StoryPack[]>{const response=await this.fetcher('/story-engine/api/catalog',{headers:{accept:'application/json'}});if(!response.ok)throw new Error(`读取内容包目录失败：${response.status}`);const body=await response.json()as{packs?:StoryPack[]};if(!Array.isArray(body.packs))throw new Error('内容包目录格式无效');return body.packs.map(pack=>pack.template===undefined?pack:{...pack,template:validateProjection({...pack.template,saveId:'catalog-template',packId:pack.packId,packTitle:pack.title,agentPreset:pack.agentPreset,revision:0,updatedAt:new Date().toISOString()})})}async list():Promise<SaveSummary[]>{const response=await this.fetcher('/story-engine/api/saves',{headers:{accept:'application/json'}});if(!response.ok)throw new Error(`读取存档列表失败：${response.status}`);const body=await response.json()as{saves?:SaveSummary[]};if(!Array.isArray(body.saves))throw new Error('存档列表格式无效');return body.saves}async load(saveId:string):Promise<StorySaveProjection|undefined>{const response=await this.fetcher(`/story-engine/api/saves/${encodeURIComponent(saveId)}`,{headers:{accept:'application/json'}});if(response.status===204||response.status===404)return undefined;if(!response.ok)throw new Error(`读取本地存档失败：${response.status}`);return validateProjection(await response.json())}save(value:StorySaveProjection,bootstrap=false):Promise<void>{const task=this.tail.then(async()=>{const response=await this.fetcher(`/story-engine/api/saves/${encodeURIComponent(value.saveId)}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({expectedRevision:bootstrap?-1:value.revision-1,projection:value})});if(response.status===409)throw new Error('宿主存档发生版本冲突：此存档已在另一窗口更新，请重新打开后再继续');if(!response.ok){const detail=await response.json().catch(()=>({}))as{error?:string};throw new Error(detail.error??`保存失败：${response.status}`)}});this.tail=task.catch(()=>{});return task}async remove(saveId:string):Promise<void>{const response=await this.fetcher(`/story-engine/api/saves/${encodeURIComponent(saveId)}`,{method:'DELETE'});if(!response.ok){const detail=await response.json().catch(()=>({}))as{error?:string};throw new Error(detail.error??`删除存档失败：${response.status}`)}}}
